-- Additive private creation custody. No policy/grant/approval is established.
-- Registration rows are generated below; all start closed and unverified.
BEGIN;
CREATE TABLE public.sandy_supabase_project_creation_dispatches (
 admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,
 project_name text NOT NULL UNIQUE CHECK(project_name ~ '^sandy-eng-[a-z0-9][a-z0-9-]{2,50}$'),
 input_sha256 text NOT NULL CHECK(input_sha256 ~ '^[a-f0-9]{64}$'),
 material_claimed_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE public.sandy_supabase_project_creation_dispatches ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sandy_supabase_project_creation_dispatches FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.sandy_supabase_project_creation_material(p_admission uuid,p_canonical_arguments text)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE a public.sandy_api_execution_admissions; r public.sandy_operation_registry;
 args jsonb; material text; matches integer;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR p_canonical_arguments IS NULL
 OR octet_length(p_canonical_arguments)>1024 THEN RAISE EXCEPTION 'internal_creation_context_required'; END IF;
 args:=p_canonical_arguments::jsonb;
 IF jsonb_typeof(args) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(args))<>2
 OR NOT(args ?& ARRAY['name','region']) OR (args->>'name') !~ '^sandy-eng-[a-z0-9][a-z0-9-]{2,50}$'
 OR jsonb_typeof(args->'name') IS DISTINCT FROM 'string' OR jsonb_typeof(args->'region') IS DISTINCT FROM 'string'
 THEN RAISE EXCEPTION 'exact_creation_arguments_required'; END IF;
 SELECT * INTO a FROM public.sandy_api_execution_admissions WHERE id=p_admission FOR UPDATE;
 SELECT * INTO r FROM public.sandy_operation_registry WHERE operation='supabase.projects.create' FOR SHARE;
 IF a.id IS NULL OR a.operation IS DISTINCT FROM 'supabase.projects.create' OR a.state IS DISTINCT FROM 'consumed'
 OR a.expires_at<=clock_timestamp() OR a.is_mutation IS DISTINCT FROM true OR a.tenant_id IS NOT NULL OR a.credential_id IS NOT NULL
 OR a.declared_cost_units<=0 OR NOT public.sandy_api_current_owner(a.actor_id)
 OR a.input_sha256 IS DISTINCT FROM encode(extensions.digest(p_canonical_arguments,'sha256'),'hex')
 OR r.handler IS DISTINCT FROM 'sandy-provider-gap-api' OR r.api_exposed IS DISTINCT FROM true OR r.verified IS DISTINCT FROM true
 OR r.error_contract->>'requires_cost_approval' IS DISTINCT FROM 'true'
 OR r.error_contract->>'contract_sha256' IS DISTINCT FROM a.contract_sha256
 OR public.sandy_api_registry_revision(a.operation) IS DISTINCT FROM a.registry_revision_sha256
 THEN RAISE EXCEPTION 'current_consumed_budgeted_creation_admission_required'; END IF;
 SELECT count(*)::integer,min(decrypted_secret) INTO matches,material FROM vault.decrypted_secrets
 WHERE name='sandy-project-create-db-password:'||(args->>'name');
 IF matches<>1 OR material IS NULL OR length(material) NOT BETWEEN 16 AND 256
 THEN RAISE EXCEPTION 'existing_project_password_custody_required'; END IF;
 INSERT INTO public.sandy_supabase_project_creation_dispatches(admission_id,project_name,input_sha256)
 VALUES(a.id,args->>'name',a.input_sha256);
 -- Material remains in this trusted server callback; no API operation returns it.
 RETURN material;
END $$;
REVOKE ALL ON FUNCTION public.sandy_supabase_project_creation_material(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sandy_supabase_project_creation_material(uuid,text) TO service_role;
